// Extract message data from Meta WhatsApp webhook payload
const body = $input.first().json;

// Meta webhook verification (GET requests handled by webhook node)
// For POST: extract message content
let phoneNumber = '';
let messageText = '';
let messageId = '';
let contactName = '';

if (body.entry && body.entry[0] && body.entry[0].changes && body.entry[0].changes[0]) {
  const change = body.entry[0].changes[0];
  if (change.value && change.value.messages && change.value.messages[0]) {
    const msg = change.value.messages[0];
    phoneNumber = msg.from || '';
    messageId = msg.id || '';
    messageText = msg.text?.body || msg.button?.text || msg.interactive?.button_reply?.title || '';

    if (change.value.contacts && change.value.contacts[0]) {
      contactName = change.value.contacts[0].profile?.name || '';
    }
  }
}

// Clean phone number for session ID
const sessionId = phoneNumber.replace(/[^0-9]/g, '');

return {
  json: {
    phoneNumber,
    sessionId,
    messageText,
    messageId,
    contactName,
    timestamp: new Date().toISOString(),
    raw: JSON.stringify(body)
  }
};

// Prepare the AI response and lead data for downstream nodes
const aiResponse = $input.first().json.output || $input.first().json.text || '';
const extractData = $('Extract Message').first().json;

// Simple lead scoring based on conversation content
const responseLower = aiResponse.toLowerCase();
const messageLower = (extractData.messageText || '').toLowerCase();
const combinedText = responseLower + ' ' + messageLower;

let leadScore = 'COLD';
let hasContactInfo = false;
let hasAddress = false;
let hasName = extractData.contactName ? true : false;

// --- Objection Detection ---
let objectionType = null;

const objectionPatterns = [
  {
    type: 'price_too_high',
    regex: /too expensive|can'?t afford|price is too high|out of my budget|paying less|fibre costs too much|not worth the money|don'?t want another monthly expense|more than i expected|too pricey|can'?t afford it/
  },
  {
    type: 'comparing_providers',
    regex: /still comparing|looking around|want to compare|getting other quotes|waiting for another provider|haven'?t decided|shopping around|checking other|comparing options/
  },
  {
    type: 'need_to_think',
    regex: /i'?ll think about|let me decide|discuss it with|discuss with my family|i'?ll get back to you|i'?ll let you know|not today|need to think|let me think|think about it/
  },
  {
    type: 'already_have_fibre',
    regex: /already have fibre|with another provider|already connected|don'?t need fibre|my internet is working|already got fibre|have internet already|current provider/
  },
  {
    type: 'moving',
    regex: /i'?m moving|relocating|new address|changing houses|moving next month|moving soon|moving to|relocation/
  }
];

for (const pattern of objectionPatterns) {
  if (pattern.regex.test(messageLower)) {
    objectionType = pattern.type;
    break;
  }
}

// --- Escalation Detection ---
let needsEscalation = false;
const escalationRegex = /discount|negotiate|custom pricing|callback|speak to a consultant|speak to a human|speak to someone|contract negotiation|can you call me|get a call|manager|supervisor|check.*availability|check.*coverage|is fibre available|check if.*available|coverage at|available at my|available at that|available at the/;
if (escalationRegex.test(messageLower)) {
  needsEscalation = true;
}

// --- Follow-up Detection ---
let followUpRequested = false;
let followUpDate = null;
const followUpRegex = /think about it|get back to you|let you know|let me decide|discuss it with|discuss with my family|not today|need to think|let me think/;
if (followUpRegex.test(messageLower)) {
  followUpRequested = true;
  const date = new Date();
  date.setDate(date.getDate() + 3);
  followUpDate = date.toISOString().split('T')[0];
}

// --- Offered Package Extraction ---
// Extract package speed and price from AI response when a follow-up is requested
let offeredPackage = null;
if (followUpRequested || objectionType === 'need_to_think') {
  // Match patterns like "20/10 Mbps at R345/month", "50 Mbps at R695/month", "20 Mbps — R345/month"
  const packageMatch = aiResponse.match(/(\d+\/?\d*)\s*Mbps[^R]*R(\d+)\s*\/\s*month/i);
  if (packageMatch) {
    offeredPackage = packageMatch[1] + ' Mbps at R' + packageMatch[2] + '/month';
  }
}

// Check for contact information patterns
if (/\b\d{10}\b|\b\d{3}[-\s]\d{3}[-\s]\d{4}\b|\b0\d{2}\s\d{3}\s\d{4}\b/.test(combinedText)) {
  hasContactInfo = true;
}
if (/\bstreet\b|\broad\b|\bavenue\b|\bdrive\b|\bplace\b|\bclose\b|\bblvd\b|\baddress\b/.test(combinedText)) {
  hasAddress = true;
}

// Scoring logic
if (hasContactInfo && hasAddress && /sign\s*up|install|apply|get\s*started|proceed|go\s*ahead|sounds\s*good|interested|let'?s\s*do\s*it/.test(combinedText)) {
  leadScore = 'HOT';
} else if (hasContactInfo || (/price|cost|how\s*much|install|when\s*can|interested|package/.test(combinedText) && hasName)) {
  leadScore = 'WARM';
}

// Objection detection overrides: minimum WARM (customer is engaged if raising an objection)
if ((objectionType || needsEscalation) && leadScore === 'COLD') {
  leadScore = 'WARM';
}

return {
  json: {
    phoneNumber: extractData.phoneNumber,
    sessionId: extractData.sessionId,
    contactName: extractData.contactName,
    incomingMessage: extractData.messageText,
    aiResponse: aiResponse,
    leadScore: leadScore,
    hasContactInfo: hasContactInfo,
    hasAddress: hasAddress,
    objectionType: objectionType,
    needsEscalation: needsEscalation,
    followUpRequested: followUpRequested,
    followUpDate: followUpDate,
    offeredPackage: offeredPackage,
    timestamp: extractData.timestamp,
    webhookReceived: true
  }
};

